mapper.select:
select t.station_code, t.station_name, t.business_type, t.province_id, t.city_id, t.county_id,
t.province_name, t.city_name, t.county_name, t.location address, t.longitude lat, t.longitude lon, t.create_time
from `vm_aiot_energy_station_info_t` t
where t.`del_flag` = 0

    and t.station_code in

        #{item}



    and t.station_code in

        #{item}



    and t.business_type = #{param.businessType}


    and t.station_code like CONCAT('%', #{param.stationCode},'%')


    and t.station_name like CONCAT('%', #{param.stationName},'%')


    and t.province_id = #{param.provinceId}


    and t.city_id = #{param.cityId}


    and t.county_id = #{param.countyId}

order by t.create_time desc, t.station_code

select t.device_code devCode, t.device_name devName, t.dev_type devType, t.business_type businessType, t.online_status onlineStatus, t.station_code stationCode, t.station_name, t.create_time, t.latitude lat, t.longitude lon, t.factory, t.location address, pro.area_name as provinceName, pro.area_code as provinceId, city.area_name as cityName, city.area_code as cityId, county.area_name as countyName, county.area_code as countyId from `vm_order_energy_devices` o inner join `vm_aiot_energy_device_info_t` t on o.device_code = t.device_code and o.category_code = t.device_type LEFT JOIN sys_area pro on pro.area_code = t.province_id LEFT JOIN sys_area city on city.area_code = t.city_id LEFT JOIN sys_area county on county.area_code = t.county_id where o.delete_flag = 0 and t.`del_flag` = 0 and o.ord_status in (0,1,2) and o.tenant_id = #{param.tenantId} and o.industry_code = #{param.industryCode}
and t.station_code in
#{item}
and t.device_type = #{param.businessType}
and t.station_code like CONCAT('%', #{param.stationCode},'%')
and t.station_name like CONCAT('%', #{param.stationName},'%')
and t.device_code like CONCAT('%', #{param.devCode},'%')
and t.device_name like CONCAT('%', #{param.devName},'%')
and t.dev_type in
#{item}
and t.province_id = #{param.provinceId}
and t.city_id = #{param.cityId}
and t.county_id = #{param.countyId}
group by t.device_code order by t.create_time desc, t.id

select distinct t.station_code
from `vm_order_energy_devices` o
inner join `vm_aiot_energy_device_info_t` t on o.device_code = t.device_code and o.category_code = t.device_type
where o.delete_flag = 0 and t.`del_flag` = 0 and o.ord_status in (0,1,2) and o.tenant_id = #{tenantId}
and o.industry_code = #{industryCode}

select distinct t.device_code
from `vm_order_energy_devices` o
inner join `vm_aiot_energy_device_info_t` t on o.device_code = t.device_code and o.category_code = t.device_type
where o.delete_flag = 0 and t.`del_flag` = 0 and o.ord_status in (0,1,2) and o.tenant_id = #{param.tenantId}
and o.industry_code = #{param.industryCode}

    and t.station_code in

        #{item}



    and t.device_type = #{param.businessType}


    and t.device_code like CONCAT('%', #{param.devCode},'%')


    and t.device_name like CONCAT('%', #{param.devName},'%')


    and t.dev_type in

        #{item}

select
count(distinct(t.device_code)) totalNum,
count(distinct case when t.online_status = 0 then t.device_code end) as offlineNum,
count(distinct case when t.online_status = 1 then t.device_code end) as onlineNum,
count(distinct case when t.online_status = 2 then t.device_code end) as noConnectedNum
from `vm_order_energy_devices` o
inner join `vm_aiot_energy_device_info_t` t on o.device_code = t.device_code and o.category_code = t.device_type
where o.delete_flag = 0 and t.`del_flag` = 0 and o.ord_status in (0,1,2) and o.tenant_id = #{param.tenantId}
and o.industry_code = #{param.industryCode}

    and t.station_code in

        #{item}



    and t.device_type = #{param.businessType}

select t.station_code, t.station_name, IFNULL(count(distinct(t.device_code)), 0) totalNum, IFNULL(count(distinct case when t.online_status = 0 then t.device_code end), 0) as offlineNum, IFNULL(count(distinct case when t.online_status = 1 then t.device_code end), 0) as onlineNum, IFNULL(count(distinct case when t.online_status = 2 then t.device_code end), 0) as noConnectedNum from `vm_order_energy_devices` o inner join `vm_aiot_energy_device_info_t` t on o.device_code = t.device_code and o.category_code = t.device_type where o.delete_flag = 0 and t.`del_flag` = 0 and o.ord_status in (0,1,2) and o.tenant_id = #{param.tenantId} and o.industry_code = #{param.industryCode}
and t.station_code in
#{item}
and t.device_type = #{param.businessType}
and t.station_code like CONCAT('%', #{param.stationCode},'%')
and t.station_name like CONCAT('%', #{param.stationName},'%')
group by t.station_code
